IF OBJECT_ID(N'gb_device', N'U') IS NOT NULL DROP TABLE [gb_device];
IF OBJECT_ID(N'gb_device', N'U') IS NULL
BEGIN
  CREATE TABLE [gb_device] (
    [id] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [device_id] NVARCHAR(20) NOT NULL DEFAULT N'',
    [name] NVARCHAR(255) NOT NULL DEFAULT N'',
    [alias] NVARCHAR(255) NOT NULL DEFAULT N'',
    [password] NVARCHAR(255) NOT NULL DEFAULT N'',
    [transport] NVARCHAR(8) NOT NULL DEFAULT N'',
    [manufacturer] NVARCHAR(255) NOT NULL DEFAULT N'',
    [model] NVARCHAR(255) NOT NULL DEFAULT N'',
    [firmware] NVARCHAR(255) NOT NULL DEFAULT N'',
    [ip] NVARCHAR(64) NOT NULL DEFAULT N'',
    [port] INT DEFAULT 0,
    [register_time] DATETIME2(3),
    [register_expire_at] DATETIME2(3),
    [keepalive_time] DATETIME2(3),
    [keepalive_interval] INT DEFAULT 60,
    [expires] INT DEFAULT 0,
    [status] TINYINT DEFAULT 0,
    [offline_at] DATETIME2(3),
    [subscribe_capability] NVARCHAR(16) NOT NULL DEFAULT N'unknown',
    [subscribe_last_test] DATETIME2(3),
    [subscribe_expires_at] DATETIME2(3),
    [created_at] DATETIME2(3),
    [updated_at] DATETIME2(3),
    [deleted_at] DATETIME2(3),
    [created_by] INT DEFAULT 0,
    [owner_dept_id] INT NOT NULL DEFAULT 0,
    [reported_version] NVARCHAR(8) NOT NULL DEFAULT N'',
    [reported_version_at] DATETIME2(3),
    [protocol_override] NVARCHAR(8) NOT NULL DEFAULT N'auto',
    [effective_version] NVARCHAR(8) NOT NULL DEFAULT N'2016',
    [effective_version_source] NVARCHAR(16) NOT NULL DEFAULT N'default',
    [effective_version_at] DATETIME2(3),
    [zlm_node_id] BIGINT NOT NULL DEFAULT 0,
    [access_epoch] BIGINT NOT NULL DEFAULT 1,
    [legacy_revoked_before] DATETIME2(3),
    [cleanup_completed_epoch] BIGINT NOT NULL DEFAULT 1,
    CONSTRAINT [uk_device_id] UNIQUE ([device_id]),
    CONSTRAINT [ck_gb_device_cleanup_completed_epoch] CHECK ((([cleanup_completed_epoch] > 0) and ([cleanup_completed_epoch] <= [access_epoch]))),
    CONSTRAINT [gb_device_chk_1] CHECK (([access_epoch] > 0))
  );
END;
