IF OBJECT_ID(N'gb_device_operation_intent', N'U') IS NOT NULL DROP TABLE [gb_device_operation_intent];
IF OBJECT_ID(N'gb_device_operation_intent', N'U') IS NULL
BEGIN
  CREATE TABLE [gb_device_operation_intent] (
    [operation_id] NVARCHAR(32) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [contract_version] BIGINT NOT NULL,
    [device_pk] BIGINT NOT NULL,
    [device_code] NVARCHAR(20) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [device_epoch] BIGINT NOT NULL,
    [target_scope] NVARCHAR(16) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [target_pk] BIGINT NOT NULL,
    [target_code] NVARCHAR(20) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [kind] NVARCHAR(16) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [state] NVARCHAR(16) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [row_version] BIGINT NOT NULL,
    [created_at] DATETIME2(6) NOT NULL,
    [updated_at] DATETIME2(6) NOT NULL,
    [dispatch_started_at] DATETIME2(6),
    [cancelled_at] DATETIME2(6),
    [rtp_steps_json] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2,
    [sip_steps_json] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2,
    PRIMARY KEY ([operation_id]),
    CONSTRAINT [ck_device_intent_identity] CHECK (([contract_version] = 1 AND [device_pk] > 0 AND [device_epoch] > 0 AND [target_pk] > 0 AND [operation_id] COLLATE Latin1_General_BIN2 LIKE '[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]' AND [device_code] COLLATE Latin1_General_BIN2 LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' AND [target_code] COLLATE Latin1_General_BIN2 LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' AND ([target_scope] = 'channel' OR ([target_scope] = 'device' AND [target_pk] = [device_pk] AND [target_code] = [device_code])) AND [kind] IN ('live', 'playback', 'download', 'talk', 'ptz'))),
    CONSTRAINT [ck_device_intent_phase] CHECK ((([updated_at] >= [created_at]) and ((([state] = 'reserved') and ([row_version] = 1) and ([dispatch_started_at] is null) and ([cancelled_at] is null)) or (([state] = 'dispatched') and ([row_version] >= 2) and ([cancelled_at] is null) and ([dispatch_started_at] is not null) and ([dispatch_started_at] >= [created_at]) and ([dispatch_started_at] <= [updated_at])) or (([state] = 'cancelled') and ([row_version] >= 2) and ([dispatch_started_at] is null) and ([cancelled_at] is not null) and ([cancelled_at] >= [created_at]) and ([cancelled_at] <= [updated_at]))))),
    CONSTRAINT [ck_device_intent_rtp_size] CHECK (([rtp_steps_json] IS NULL OR DATALENGTH([rtp_steps_json]) BETWEEN 2 AND 65536)),
    CONSTRAINT [ck_device_intent_sip_size] CHECK (([sip_steps_json] IS NULL OR DATALENGTH([sip_steps_json]) BETWEEN 2 AND 65536))
  );
END;
