IF OBJECT_ID(N'gb_openapi_play_grant', N'U') IS NULL
BEGIN
  CREATE TABLE [gb_openapi_play_grant] (
    [grant_id] NCHAR(36) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [client_id] BIGINT NOT NULL,
    [scope] NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [device_id] NVARCHAR(20) COLLATE Latin1_General_100_BIN2,
    [channel_id] NVARCHAR(20) COLLATE Latin1_General_100_BIN2,
    [client_epoch] BIGINT NOT NULL DEFAULT 1,
    [scope_epoch] BIGINT NOT NULL DEFAULT 1,
    [device_epoch] BIGINT NOT NULL DEFAULT 1,
    [node_uuid] NVARCHAR(64) COLLATE Latin1_General_100_BIN2,
    [boot_nonce] NCHAR(32) COLLATE Latin1_General_100_BIN2,
    [schema] NVARCHAR(32) COLLATE Latin1_General_100_BIN2,
    [vhost] NVARCHAR(128) COLLATE Latin1_General_100_BIN2,
    [app] NVARCHAR(64) COLLATE Latin1_General_100_BIN2,
    [stream] NVARCHAR(255) COLLATE Latin1_General_100_BIN2,
    [media_generation] BIGINT,
    [protocol] NVARCHAR(16) COLLATE Latin1_General_100_BIN2,
    [issued_at] DATETIME2(6) NOT NULL,
    [expires_at] DATETIME2(6) NOT NULL,
    [state] NVARCHAR(16) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'pending',
    [reason] NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'',
    [created_at] DATETIME2(6) NOT NULL,
    [updated_at] DATETIME2(6) NOT NULL,
    PRIMARY KEY ([grant_id]),
    CONSTRAINT [ck_openapi_grant_binding] CHECK ((([state] not in ('issued','bound')) or (([device_id] is not null) and ([channel_id] is not null) and ([node_uuid] is not null) and ([boot_nonce] is not null) and (char_length([boot_nonce]) = 32) and ([schema] is not null) and ([device_id] <> '') and ([channel_id] <> '') and ([node_uuid] <> '') and ([boot_nonce] <> '') and ([schema] <> '') and ([vhost] is not null) and ([vhost] <> '') and ([app] is not null) and ([app] <> '') and ([stream] is not null) and ([stream] <> '') and ([media_generation] is not null) and ([media_generation] > 0) and ([protocol] is not null) and ([protocol] <> '')))),
    CONSTRAINT [ck_openapi_grant_epochs] CHECK ((([client_epoch] > 0) and ([scope_epoch] > 0) and ([device_epoch] > 0))),
    CONSTRAINT [ck_openapi_grant_state] CHECK (([state] in ('pending','issued','bound','revoked','expired','failed')))
  );
END;
