    CONSTRAINT [ck_openapi_viewer_media_binding] CHECK ((([schema] <> '') and ([vhost] <> '') and ([app] <> '') and ([stream] <> '') and ([media_generation] > 0))),
    CONSTRAINT [ck_openapi_viewer_media_generation] CHECK (([media_generation] > 0)),
