    [refresh_token_hash] NCHAR(64),
    [refresh_jti] NVARCHAR(36),
    [client_ip] NVARCHAR(50) NOT NULL DEFAULT N'',
    [login_location] NVARCHAR(100) NOT NULL DEFAULT N'未知',
    [user_agent] NVARCHAR(500) NOT NULL DEFAULT N'',
    [browser] NVARCHAR(100) NOT NULL DEFAULT N'未知',
    [os] NVARCHAR(100) NOT NULL DEFAULT N'未知',
    [login_at] DATETIME2(3) NOT NULL,
    [last_active_at] DATETIME2(3) NOT NULL,
    [session_expires_at] DATETIME2(3) NOT NULL,
    [revoked_at] DATETIME2(3),
    [revoke_reason] NVARCHAR(32),
    [revoked_by] BIGINT,
    [created_at] DATETIME2(3),
    [updated_at] DATETIME2(3),
    PRIMARY KEY ([sid])
  );
END;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'sys_user_sessions') AND name=N'idx_client_ip')
  CREATE INDEX [idx_client_ip] ON [sys_user_sessions] ([client_ip]);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'sys_user_sessions') AND name=N'idx_session_valid')
  CREATE INDEX [idx_session_valid] ON [sys_user_sessions] ([revoked_at], [session_expires_at], [login_at]);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'sys_user_sessions') AND name=N'idx_user_id')
  CREATE INDEX [idx_user_id] ON [sys_user_sessions] ([user_id]);

IF OBJECT_ID(N'sys_users', N'U') IS NOT NULL DROP TABLE [sys_users];
IF OBJECT_ID(N'sys_users', N'U') IS NULL
BEGIN
  CREATE TABLE [sys_users] (
    [id] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [username] NVARCHAR(50) NOT NULL DEFAULT N'',
    [password] NVARCHAR(255) NOT NULL DEFAULT N'',
    [email] NVARCHAR(100) DEFAULT N'',
    [status] TINYINT DEFAULT 1,
    [dept_id] INT DEFAULT 0,
    [phone] NVARCHAR(64) DEFAULT N'',
    [sex] NVARCHAR(64) DEFAULT N'',
    [nick_name] NVARCHAR(100) DEFAULT N'',
    [avatar] NVARCHAR(255) DEFAULT N'',
    [description] NVARCHAR(500),
    [created_at] DATETIME2(3),
    [updated_at] DATETIME2(3),
    [deleted_at] DATETIME2(3),
    [created_by] INT DEFAULT 0,
    CONSTRAINT [username] UNIQUE ([username])
  );
END;

