    [id] BIGINT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [group_id] BIGINT NOT NULL,
    [code] NVARCHAR(96) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [scope] NVARCHAR(96) COLLATE Latin1_General_100_BIN2 NOT NULL,
