    [risk_level] NVARCHAR(16) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'read',
    [status] NVARCHAR(16) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'draft',
    [sys_api_id] BIGINT,
    [sys_api_path] NVARCHAR(255) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'',
    [sys_api_method] NVARCHAR(16) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'',
    [published_at] DATETIME2(6),
    [row_version] BIGINT NOT NULL DEFAULT 1,
    [created_by] BIGINT NOT NULL DEFAULT 0,
    [updated_by] BIGINT NOT NULL DEFAULT 0,
    [created_at] DATETIME2(6) NOT NULL,
    [updated_at] DATETIME2(6) NOT NULL,
    [deleted_at] DATETIME2(6),
    CONSTRAINT [uk_openapi_capability_group_capability_code] UNIQUE ([group_id], [code]),
    CONSTRAINT [uk_openapi_capability_scope] UNIQUE ([scope])
  );
END;
