  CREATE INDEX [idx_openapi_capability_group_deleted] ON [sys_openapi_capability_group] ([deleted_at]);

IF OBJECT_ID(N'sys_openapi_operation', N'U') IS NOT NULL DROP TABLE [sys_openapi_operation];
IF OBJECT_ID(N'sys_openapi_operation', N'U') IS NULL
BEGIN
  CREATE TABLE [sys_openapi_operation] (
    [id] BIGINT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [capability_id] BIGINT NOT NULL,
    [code] NVARCHAR(96) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [name] NVARCHAR(160) COLLATE Latin1_General_100_BIN2 NOT NULL,
