    [external_path] NVARCHAR(255) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [adapter_key] NVARCHAR(96) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [adapter_contract_version] NVARCHAR(32) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'v1',
    [resource_type] NVARCHAR(32) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'',
    [risk_level] NVARCHAR(16) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'read',
    [idempotency_mode] NVARCHAR(16) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'none',
    [request_schema] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [response_schema] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
