    [response_schema] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [sys_api_id] BIGINT,
    [sys_api_path] NVARCHAR(255) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'',
    [sys_api_method] NVARCHAR(16) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT N'',
    [sort] INT NOT NULL DEFAULT 0,
    [snapshot_json] NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
    [created_at] DATETIME2(6) NOT NULL,
    CONSTRAINT [uk_openapi_release_item_route] UNIQUE ([release_id], [method], [external_path])
  );
END;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'sys_openapi_release_item') AND name=N'idx_openapi_release_item_capability')
